1	/**
2	 * Encapsulates input data for LCS computation with validation.
3	 */
4	class LcsInput {
5	    private final String firstString;
6	    private final String secondString;
7	
8	    /**
9	     * Constructs an LcsInput with validation.
10	     *
11	     * @param firstString  the first string (non-null)
12	     * @param secondString the second string (non-null)
13	     * @throws IllegalArgumentException if either string is null
14	     */
15	    public LcsInput(String firstString, String secondString) {
16	        if (firstString == null || secondString == null) {
17	            throw new IllegalArgumentException("Input strings cannot be null");
18	        }
19	        this.firstString = firstString;
20	        this.secondString = secondString;
21	    }
22	
23	    public String getFirstString() {
24	        return firstString;
25	    }
26	
27	    public String getSecondString() {
28	        return secondString;
29	    }
30	}
