32	/**
33	 * Encapsulates the result of LCS computation.
34	 */
35	class LcsResult {
36	    private final int length;
37	
38	    public LcsResult(int length) {
39	        this.length = length;
40	    }
41	
42	    public int getLength() {
43	        return length;
44	    }
45	}
