47	/**
48	 * Interface for LCS solver implementations.
49	 */
50	interface LcsSolver {
51	    /**
52	     * Computes the length of the Longest Common Subsequence.
53	     *
54	     * @param input the LcsInput containing two strings
55	     * @return LcsResult with the length of the LCS
56	     */
57	    LcsResult solve(LcsInput input);
58	}
59	
60	/**
61	 * Standard dynamic programming implementation of LCS algorithm.
62	 */
63	class StandardLcsSolver implements LcsSolver {
64	    /**
65	     * Computes the length of the Longest Common Subsequence using DP.
66	     * Time complexity: O(m * n), Space complexity: O(m * n)
67	     *
68	     * @param input the LcsInput containing two strings
69	     * @return LcsResult with the length of the LCS
70	     */
71	    @Override
72	    public LcsResult solve(LcsInput input) {
73	        String s1 = input.getFirstString();
74	        String s2 = input.getSecondString();
75	
76	        int m = s1.length();
77	        int n = s2.length();
78	        int[][] dpTable = new int[m + 1][n + 1];
79	
80	        for (int i = 1; i <= m; i++) {
81	            for (int j = 1; j <= n; j++) {
82	                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
83	                    dpTable[i][j] = dpTable[i - 1][j - 1] + 1;
84	                } else {
85	                    dpTable[i][j] = Math.max(dpTable[i - 1][j],
86	                                              dpTable[i][j - 1]);
87	                }
88	            }
89	        }
90	
91	        return new LcsResult(dpTable[m][n]);
92	    }
93	}
94	
95	/**
96	 * Backward-compatible wrapper maintaining original static API.
97	 */
98	class LongestCommonSubsequence {
99	    private static final LcsSolver solver = new StandardLcsSolver();
100	
101	    /**
102	     * Computes the length of the Longest Common Subsequence.
103	     * Backward-compatible convenience method using standard DP solver.
104	     *
105	     * @param s1 first string
106	     * @param s2 second string
107	     * @return length of the LCS
108	     * @throws IllegalArgumentException if either string is null
109	     */
110	    static int lcs(String s1, String s2) {
111	        LcsInput input = new LcsInput(s1, s2);
112	        return solver.solve(input).getLength();
113	    }
114	}
