1	import java.util.HashMap;
2	import java.util.Map;
3	
4	/**
5	 * Decorator pattern implementation for caching LCS results.
6	 * Wraps any LcsSolver implementation and caches results for repeated queries.
7	 *
8	 * Useful when the same string pairs are compared multiple times.
9	 * Cache key is based on both strings to ensure correctness across different orderings.
10	 */
11	class CachedLcsSolver implements LcsSolver {
12	    private final LcsSolver delegate;
13	    private final Map<String, Integer> cache;
14	
15	    /**
16	     * Creates a cached solver wrapping the provided solver.
17	     *
18	     * @param delegate the underlying LcsSolver to cache results for
19	     */
20	    public CachedLcsSolver(LcsSolver delegate) {
21	        this.delegate = delegate;
22	        this.cache = new HashMap<>();
23	    }
24	
25	    /**
26	     * Solves LCS with caching. Returns cached result if available.
27	     *
28	     * @param input the LcsInput containing two strings
29	     * @return LcsResult with the length of the LCS (from cache if available)
30	     */
31	    @Override
32	    public LcsResult solve(LcsInput input) {
33	        String cacheKey = generateCacheKey(input.getFirstString(), input.getSecondString());
34	
35	        // Check cache first
36	        if (cache.containsKey(cacheKey)) {
37	            return new LcsResult(cache.get(cacheKey));
38	        }
39	
40	        // Compute and cache the result
41	        LcsResult result = delegate.solve(input);
42	        cache.put(cacheKey, result.getLength());
43	
44	        return result;
45	    }
46	
47	    /**
48	     * Generates a cache key from two strings.
49	     * Uses a canonical form to ensure symmetry (lcs(A,B) uses same cache as lcs(B,A)).
50	     *
51	     * @param s1 first string
52	     * @param s2 second string
53	     * @return cache key
54	     */
55	    private String generateCacheKey(String s1, String s2) {
56	        // Create symmetric cache key to handle both (s1,s2) and (s2,s1)
57	        if (s1.compareTo(s2) <= 0) {
58	            return s1 + "||" + s2;
59	        } else {
60	            return s2 + "||" + s1;
61	        }
62	    }
63	
64	    /**
65	     * Clears the cache.
66	     */
67	    public void clearCache() {
68	        cache.clear();
69	    }
70	
71	    /**
72	     * Returns the current cache size.
73	     *
74	     * @return number of entries in the cache
75	     */
76	    public int getCacheSize() {
77	        return cache.size();
78	    }
79	}
