1	/**
2	 * Extends LCS capability to reconstruct the actual longest common subsequence string.
3	 * This class maintains the full DP table to enable backtracking through the solution.
4	 */
5	class LcsSequenceReconstructor {
6	    /**
7	     * Reconstructs the actual LCS string from two input strings.
8	     *
9	     * Algorithm:
10	     * 1. Compute DP table (same as standard LCS)
11	     * 2. Backtrack from dp[m][n] to dp[0][0]:
12	     *    - If chars match, char is part of LCS, move diagonally
13	     *    - If chars don't match, move in direction of larger value
14	     *
15	     * Time complexity: O(m * n) for DP + O(m + n) for backtracking = O(m * n)
16	     * Space complexity: O(m * n) for DP table + O(min(m,n)) for result
17	     *
18	     * @param s1 first string
19	     * @param s2 second string
20	     * @return the LCS string
21	     * @throws IllegalArgumentException if either string is null
22	     */
23	    public static String reconstructLcs(String s1, String s2) {
24	        if (s1 == null || s2 == null) {
25	            throw new IllegalArgumentException("Input strings cannot be null");
26	        }
27	
28	        int m = s1.length();
29	        int n = s2.length();
30	
31	        // Build DP table
32	        int[][] dpTable = new int[m + 1][n + 1];
33	
34	        for (int i = 1; i <= m; i++) {
35	            for (int j = 1; j <= n; j++) {
36	                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
37	                    dpTable[i][j] = dpTable[i - 1][j - 1] + 1;
38	                } else {
39	                    dpTable[i][j] = Math.max(dpTable[i - 1][j],
40	                                              dpTable[i][j - 1]);
41	                }
42	            }
43	        }
44	
45	        // Backtrack to reconstruct the sequence
46	        StringBuilder lcs = new StringBuilder();
47	        int i = m;
48	        int j = n;
49	
50	        while (i > 0 && j > 0) {
51	            // If characters match, include in result and move diagonally
52	            if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
53	                lcs.insert(0, s1.charAt(i - 1));
54	                i--;
55	                j--;
56	            }
57	            // Otherwise, move in the direction of the larger value
58	            else if (dpTable[i - 1][j] > dpTable[i][j - 1]) {
59	                i--;
60	            } else {
61	                j--;
62	            }
63	        }
64	
65	        return lcs.toString();
66	    }
67	
68	    /**
69	     * Convenience method using LcsInput.
70	     *
71	     * @param input the LcsInput containing two strings
72	     * @return the LCS string
73	     */
74	    public static String reconstructLcs(LcsInput input) {
75	        return reconstructLcs(input.getFirstString(), input.getSecondString());
76	    }
77	}
