1	class TestCaching {
2	    public static void main(String[] args) {
3	        LcsSolver baseSolver = new StandardLcsSolver();
4	        CachedLcsSolver cachedSolver = new CachedLcsSolver(baseSolver);
5	
6	        System.out.println("=== Testing CachedLcsSolver ===\n");
7	
8	        // Test 1: Same query twice should use cache
9	        LcsInput input1 = new LcsInput("ABCDEF", "FBDAMN");
10	        System.out.println("Test 1: Repeated Queries");
11	        System.out.println("Query 1: \"ABCDEF\" vs \"FBDAMN\"");
12	        int result1 = cachedSolver.solve(input1).getLength();
13	        System.out.println("  Result: " + result1 + " (computed)");
14	        System.out.println("  Cache size: " + cachedSolver.getCacheSize());
15	
16	        System.out.println("Query 1 (again): \"ABCDEF\" vs \"FBDAMN\"");
17	        int result2 = cachedSolver.solve(input1).getLength();
18	        System.out.println("  Result: " + result2 + " (from cache)");
19	        System.out.println("  Cache size: " + cachedSolver.getCacheSize());
20	
21	        assert result1 == result2 : "Results should match";
22	
23	        // Test 2: Reversed strings (symmetric cache)
24	        System.out.println("\nTest 2: Symmetry (reversed argument order)");
25	        LcsInput input2 = new LcsInput("FBDAMN", "ABCDEF");
26	        System.out.println("Query: \"FBDAMN\" vs \"ABCDEF\"");
27	        int result3 = cachedSolver.solve(input2).getLength();
28	        System.out.println("  Result: " + result3 + " (from cache - symmetric)");
29	        System.out.println("  Cache size: " + cachedSolver.getCacheSize());
30	
